				I[365] = new("TextLabel", I[362], "Description", { AnchorPoint = Vector2.new(0, 1), BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Nunito.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal), Position = UDim2.fromScale(0, 0.662283), Size = UDim2.fromScale(1.0000001, 0.4099816), Text = "Everytime you put cash into a game you have a chance to either lose the cash you put in, break even and get your cash back, or win more cash than what you put in. There are no guarantees and your outcome is determinted from random number generation. Skill is also a factor in a few games (such as texas hold'em).", TextColor3 = Color3.fromRGB(255, 255, 255), TextScaled = true, TextSize = 14, TextStrokeTransparency = 0, TextWrapped = true })
