				I[371] = new("TextLabel", I[368], "Description", { AnchorPoint = Vector2.new(0, 1), BackgroundColor3 = Color3.fromRGB(255, 255, 255), BackgroundTransparency = 1, FontFace = Font.new("rbxasset://fonts/families/Nunito.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal), Position = UDim2.fromScale(0, 0.233632), Size = UDim2.fromScale(1.0000001, 0.2347825), Text = "If you leave a tabletop game mid-round any cash you put into the game will be lost, so try not to leave until the round is finished.", TextColor3 = Color3.fromRGB(255, 255, 255), TextScaled = true, TextSize = 14, TextStrokeTransparency = 0, TextWrapped = true })
